@register('Hermite-ODE-discriminant','ODE-lowering-resultant-discriminant','Recover a global product of every pairwise root separation through lowering operators and a resultant recursion, without solving any individual root.','The rejected root-moment prompt needed two coefficients and Newton sums; this needs a degree-lowering identity and an inter-degree product argument.',[{'n':n} for n in range(8,18)],'polynomial-ODE-and-resultant-recursion',('polynomial differential equations','products over roots'))
def discriminant(n):
 N=n*(n-1)/2;answer=s.prod(k**k for k in range(1,int(n)+1))/2**N
 P=s.expand(s.hermite(n,x)/2**n);Pm=s.expand(s.hermite(n-1,x)/2**(n-1));Pm2=s.expand(s.hermite(n-2,x)/2**(n-2))
 pool=[(answer*2**N,'forget the monic Hermite half in each recurrence factor'),(answer/2**N,'apply the monic normalization twice'),(answer/n**n,'omit the derivative lowering factor at all roots'),(answer*n**n,'apply the derivative lowering factor twice'),(answer/s.factorial(n),'replace k raised to k by k raised to k minus one'),(answer*s.factorial(n),'count each degree factor once too often')]
 Q=T('Let P be the unique monic polynomial of degree ')+L(n)+T(' satisfying the differential equation. List its complex roots with multiplicity as indicated. Evaluate the displayed product.')+r'\quad P\prime\prime-2xP\prime+'+L(2*n)+r'P=0,\qquad r_1,\ldots,r_{'+L(n)+r'},\qquad\prod_{1\le i<j\le'+L(n)+r'}(r_i-r_j)^2=?'
 steps=[T('For every nonnegative integer k, let P_k be the monic degree-k solution of the analogous equation. Comparing coefficients gives existence and uniqueness, with ')+r'P_0=1,\quad P_1=x.',T('Differentiating its differential equation shows that the derivative divided by k is the previous monic solution. Combining that identity with the equation at degree k minus one gives ')+r'P_k\prime=kP_{k-1},\qquad P_k=xP_{k-1}-\frac{k-1}{2}P_{k-2}.',T('No root can be repeated: simultaneous zero value and derivative would force the entire differential-equation solution to vanish. Define the inter-degree product over all roots of P_k.'),r'R_k=\prod_{P_k(r)=0}P_{k-1}(r),\qquad R_1=1.',T('Reverse the products over the two root sets. The sign is positive because k times k minus one is even. At a root of the previous polynomial, the three-term recurrence removes its first term.'),r'R_k=\prod_{P_{k-1}(u)=0}P_k(u)=\left(-\frac{k-1}{2}\right)^{k-1}R_{k-1}.',T('The derivative product counts each pair difference in both orientations, whereas the requested discriminant counts its square once.'),r'\prod_{i<j}(r_i-r_j)^2=(-1)^{k(k-1)/2}\prod_{P_k(r)=0}P_k\prime(r)=(-1)^{k(k-1)/2}k^kR_k.',r'\prod_{i<j}(r_i-r_j)^2=2^{-k(k-1)/2}\prod_{j=1}^{k}j^j\quad\textnormal{at }k='+L(n)+r'.']
 checks=[check('independently constructed polynomial ODE',s.diff(P,x,2)-2*x*s.diff(P,x)+2*n*P),check('lowering identity polynomial',s.diff(P,x),n*Pm),check('three-term recurrence polynomial',P,x*Pm-(n-1)*Pm2/2),check('independent exact polynomial discriminant',s.discriminant(P,x),answer),truth('chosen degree beyond routine explicit roots',bool(n>=8))]
 return item(Q,answer,pool,steps,checks,['Roots are complex roots with multiplicity; the proof itself shows simplicity. Monic means leading coefficient one. The product is invariant under root ordering.'],['Coefficient comparison recursively determines a unique monic polynomial because all lower-degree coefficient multipliers 2(k-j) are nonzero. The lowering identity follows by differentiating the equation and using uniqueness. The recurrence can be checked as a polynomial ODE identity with the same monic normalization. A repeated root would give zero initial data for a linear ODE with entire coefficients and thus the zero polynomial, a contradiction. Product reversal contributes (-1)^(k(k-1))=1. The signed derivative product then gives the stated discriminant, independently checked by the exact resultant algorithm.'],'monic-Hermite-ODE-all-pair-root-discriminant',sourceRecordIds=['q4-reference-dlmf-orthogonal-recurrences'])

@register('Mathieu-resonant-growth','degenerate-Floquet-monodromy-splitting','Split the repeated unperturbed monodromy eigenvalue by a first-order interaction-frame integral, then convert spectral radius into exponential growth.','The rotating-instability family has a constant-coefficient rotating frame; here the first-order splitting of a repeated return eigenvalue is the central perturbative decision.',[{'a':str(R(1,k))} for k in range(2,12)],'Floquet-interaction-frame-perturbation',('fundamental matrices','eigenvalue perturbation','trigonometric integrals'))
def mathieu(a):
 answer=s.sqrt(1-a*a)/2;h=a+2*s.cos(2*t);Rmat=s.Matrix([[s.cos(t),s.sin(t)],[-s.sin(t),s.cos(t)]]);B=s.Matrix([[0,0],[-h,0]]);integrand=Rmat.T*B*Rmat;K=s.Matrix([[0,s.pi*(a-1)/2],[-s.pi*(a+1)/2,0]])
 pool=[(s.sqrt(1-a*a),'omit division by the return interval'),(s.sqrt(1-a*a)/4,'halve the resonant interaction twice'),(s.sqrt(1-a)/2,'lose the squared detuning in the determinant'),(s.sqrt(1+a*a)/2,'reverse the determinant subtraction'),(s.sqrt(1+a)/2,'use only one off-diagonal interaction factor'),(s.Integer(0),'average the coefficient before transforming into the rotating frame'),(s.sqrt(1-a*a)/s.pi,'divide by the period but omit the trigonometric integral normalization')]
 Q=r'y\prime\prime+\left[1+\varepsilon\left('+L(a)+r'+2\cos2t\right)\right]y=0.'+T('Let the displayed return matrix carry the state from time zero to pi. Its spectral radius is the largest modulus of its eigenvalues. Find the following one-sided limit.')+r'\quad\binom{y(\pi)}{y\prime(\pi)}=M_\varepsilon\binom{y(0)}{y\prime(0)},\qquad\lim_{\varepsilon\downarrow0}\frac{\ln\rho(M_\varepsilon)}{\pi\varepsilon}=?'
 steps=[T('The fundamental matrix of the equation at epsilon zero is ')+r'R(t)=\begin{pmatrix}\cos t&\sin t\\-\sin t&\cos t\end{pmatrix},\qquad R(\pi)=-I_2.',T('Write the full fundamental matrix as R times Z. The interaction equation and its first-order integral are ')+r'Z\prime=\varepsilon R^{-1}B(t)RZ,\quad Z(0)=I_2,\qquad B(t)=\begin{pmatrix}0&0\\-('+L(a)+r'+2\cos2t)&0\end{pmatrix}.',r'Z(\pi)=I_2+\varepsilon K+O(\varepsilon^2),\qquad K=\int_0^\pi R^{-1}BR\,\mathrm dt=\frac\pi2\begin{pmatrix}0&'+L(a-1)+r'\\-'+L(a+1)+r'&0\end{pmatrix}.',T('The two eigenvalues of K are distinct and real. Therefore the two eigenvalues of the scaled perturbation of minus M converge to them.'),r'\operatorname{eig}(K)=\left\{\pm\frac\pi2\sqrt{1-('+L(a)+r')^2}\right\},\qquad\rho(M_\varepsilon)=1+\frac{\pi\varepsilon}{2}\sqrt{1-('+L(a)+r')^2}+O(\varepsilon^2).',T('Use the first-order natural-logarithm expansion and divide by the stated period normalization.')]
 checks=[check('unperturbed fundamental matrix',s.diff(Rmat,t),s.Matrix([[0,1],[-1,0]])*Rmat),check('exact interaction integral',integrand.applyfunc(lambda f:s.integrate(s.expand_trig(f),(t,0,s.pi))),K),check('eigenvalue square identity',K*K,s.pi*s.pi*(1-a*a)*s.eye(2)/4),truth('distinct real split eigenvalues',bool(0<a<1))]
 return item(Q,answer,pool,steps,checks,['The return interval is pi. I_2 is the two-dimensional identity. Epsilon decreases to zero through positive values. The spectral radius is the maximum of the absolute values of both eigenvalues.'],['All matrix coefficients are smooth and bounded on the compact return interval. The Volterra integral equation for Z, together with a uniform Gronwall bound, gives the O(epsilon squared) remainder in its first Picard iterate. Minus M equals Z(pi). The rescaled difference (Z(pi)-I)/epsilon converges to K, whose two eigenvalues are distinct and real; standard two-by-two characteristic-root continuity therefore gives the displayed first-order eigenvalues. Their larger modulus is positive and has the stated logarithmic expansion. This is a perturbative proof, not a numerical Floquet fit.'],'Mathieu-near-resonance-degenerate-monodromy-growth',sourceRecordIds=['q4-reference-dlmf-mathieu-floquet'])

@register('inverse-ODE-coefficient-asymptotic','inverse-function-coefficient-singularity','Integrate a nonlinear analytic ODE into an inverse relation, extract its sparse Taylor coefficients, and match their exponential and algebraic asymptotic scales.','Related to series inverse-function and Lagrange-inversion constructions; this is one global idea group across all integer nonlinearities, not one new idea for each exponent.',[{'m':m} for m in range(2,12)],'inverse-ODE-Lagrange-and-Stirling',('analytic inverse function','Lagrange coefficient inversion','Stirling formula'))
def inverse_coeff(m):
 answer=1/s.sqrt(2*s.pi*m*(m+1));rad=m/(m+1)
 pool=[(s.sqrt((m+1)/(2*s.pi*m)),'omit the sparse-index denominator normalization'),(1/s.sqrt(2*s.pi*m),'omit the extra inverse-coordinate radius factor'),(1/s.sqrt(2*s.pi*(m+1)),'omit the nonlinearity factor in the Stirling prefactor'),(1/s.sqrt(2*s.pi*m*(m+1)**2),'include the inverse radius a second time'),(1/s.sqrt(2*s.pi*m*m*(m+1)),'divide by the nonlinear degree twice'),(1/s.sqrt(s.pi*m*(m+1)),'omit the factor two in Stirling normalization')]
 Q=T('Let y be the real analytic solution near zero and define its Taylor coefficients by the displayed convergent series. Find the limit.')+r'\quad y\prime=\frac1{1-y^{'+L(m)+r'}},\quad y(0)=0,\quad y(x)=\sum_{j=0}^{\infty}a_jx^j,\qquad\lim_{n\to\infty}n^{3/2}\left('+L(rad)+r'\right)^{'+L(m)+r'n+1}a_{'+L(m)+r'n+1}=?'
 steps=[T('Integrate the inverse differential relation. The derivative of its right side at zero is one, so it has a unique analytic local inverse.'),r'x=y-\frac{y^{'+L(m+1)+r'}}{'+L(m+1)+r'},\qquad y=x\left(1-\frac{y^{'+L(m)+r'}}{'+L(m+1)+r'}\right)^{-1}.',T('For an analytic inverse of the form y=x Phi(y), Lagrange inversion says that the coefficient of x to power k is one over k times the coefficient of u to power k minus one in Phi(u) to power k. Apply it to the displayed inverse relation.'),r'a_{'+L(m)+r'n+1}=\frac1{'+L(m)+r'n+1}[u^{'+L(m)+r'n}]\left(1-\frac{u^{'+L(m)+r'}}{'+L(m+1)+r'}\right)^{-('+L(m)+r'n+1)}=\frac1{('+L(m)+r'n+1)('+L(m+1)+r')^n}\binom{'+L(m+1)+r'n}{n}.',T('All other positive-index coefficients vanish unless the index is one modulo the nonlinear degree. Apply Stirling to the factorial quotient just obtained.'),r'\binom{'+L(m+1)+r'n}{n}\sim\sqrt{\frac{'+L(m+1)+r'}{2\pi '+L(m)+r'n}}\left(\frac{'+L((m+1)**(m+1))+r'}{'+L(m**m)+r'}\right)^n.',T('The normalization in the question cancels the exponential growth. The sparse-index denominator and the remaining square root give the limit.')]
 checks=[]
 for n in range(5):
  k=int(m)*n+1;u=s.symbols('u');coef=s.diff((1-u/(m+1))**(-k),u,n).subs(u,0)/s.factorial(n)/k;expected=s.binomial((m+1)*n,n)/((m*n+1)*(m+1)**n)
  checks.append(check('independent binomial inversion coefficient n='+str(n),coef,expected))
 n=s.symbols('n',positive=True);checks.append(check('Stirling prefactor normalization',rad*s.sqrt((m+1)/(2*s.pi*m))/m,answer));checks.append(check('exponential cancellation',rad**m*(m+1)**(m+1)/(m**m*(m+1)),1))
 # Independently substitute a finite inverse series into its defining polynomial.
 Y=sum(s.binomial((m+1)*j,j)*x**(int(m)*j+1)/((m*j+1)*(m+1)**j) for j in range(4));checks.append(check('truncated inverse residual independent substitution',s.series(Y-Y**(m+1)/(m+1)-x,x,0,3*int(m)+2).removeO()))
 return item(Q,answer,pool,steps,checks,['Taylor coefficients use ordinary powers, without factorial normalization. The analytic solution and its inverse are only asserted near zero; the requested sequence asymptotic follows from exact coefficients.'],['The analytic inverse-function theorem applies to f(y)=y-y^(m+1)/(m+1) because f(0)=0 and f prime(0)=1. Differentiating the inverse identity recovers the ODE and initial condition. Lagrange inversion is an explicit theorem prerequisite, and its coefficient extraction reduces to the generalized binomial theorem with positive integer exponent. The resulting exact factorial formula for every n permits Stirling directly; no interchange of an asymptotic limit with a Taylor series is made. All nonlinear degree choices lie in the explicit finite integer domain.'],'analytic-inverse-ODE-sparse-coefficient-asymptotic',sourceRecordIds=[])

